using System;using System.Collections.Generic;using System.Linq;using UnityEngine;using UnityEditor;using LWS.TruckSports;using LWS.TruckSports.Editor;using LWS.TruckMechanicalBull.Editor;
namespace LWS.TruckTeaParty.Editor {
 // Shared Tea/Bake original serving models; existing lathe/bevel production
 // tooling remains the mesh foundation, never regenerated during play.
 public static class ServingArt {
  public static Mesh Mesh(string folder,string name,Func<Mesh> build)=>ImpossibleBalanceArt.Mesh(folder,name,build);
  public static GameObject Part(string folder,Transform parent,string name,Mesh mesh,Material material,Vector3 p,Vector3 scale)=>ImpossibleBalanceArt.Part(parent,name,mesh,material,p,scale);
  public static Mesh Block(string folder)=>Mesh(folder,"Original bevelled serving furniture",ImpossibleBalanceArt.RoundedBlock);
  public static Mesh Disk(string folder)=>Mesh(folder,"Glazed circular doily and liquid surface",()=>ImpossibleBalanceArt.Lathe(new[]{new Vector2(0,0),new Vector2(1,0),new Vector2(1,.05f),new Vector2(0,.05f)},48));
  public static Mesh Ring(string folder)=>Mesh(folder,"Fine rolled gold porcelain lip",()=>ImpossibleBalanceArt.Lathe(new[]{new Vector2(.88f,0),new Vector2(1,0),new Vector2(1,.12f),new Vector2(.88f,.12f),new Vector2(.88f,0)},48));
  public static Mesh Cup(string folder)=>Mesh(folder,"Actual hollow English porcelain teacup",()=>ImpossibleBalanceArt.Lathe(new[]{new Vector2(.68f,0),new Vector2(.76f,.1f),new Vector2(.8f,.3f),new Vector2(.92f,1.25f),new Vector2(.98f,1.4f),new Vector2(.94f,1.5f),new Vector2(.82f,1.5f),new Vector2(.79f,1.25f),new Vector2(.64f,.18f),new Vector2(0,.18f),new Vector2(0,0),new Vector2(.68f,0)},48));
  public static Mesh Pot(string folder)=>Mesh(folder,"Round glazed hand-thrown teapot body",()=>ImpossibleBalanceArt.Lathe(new[]{new Vector2(0,0),new Vector2(.6f,0),new Vector2(.95f,.3f),new Vector2(1.2f,.85f),new Vector2(1.05f,1.3f),new Vector2(.7f,1.65f),new Vector2(.64f,1.72f),new Vector2(.57f,1.72f),new Vector2(.8f,1.25f),new Vector2(.9f,.6f),new Vector2(0,.22f),new Vector2(0,0)},48));
  public static Mesh Spout(string folder)=>Mesh(folder,"Curved open porcelain pouring spout",()=>{var vertices=new List<Vector3>();var uv=new List<Vector2>();var tris=new List<int>();const int rows=16,sides=20;for(int side=0;side<2;side++)for(int row=0;row<=rows;row++){float t=row/(float)rows;var center=new Vector3(0,.4f+t*.7f,.8f+t*1.4f);float radius=Mathf.Lerp(.45f,.16f,t)-(side==1?.07f:0);for(int i=0;i<=sides;i++){float a=i*Mathf.PI*2/sides;vertices.Add(center+new Vector3(Mathf.Cos(a)*radius,Mathf.Sin(a)*radius,0));uv.Add(new Vector2(i/(float)sides,t));}}int offset=(rows+1)*(sides+1);for(int side=0;side<2;side++)for(int row=0;row<rows;row++)for(int i=0;i<sides;i++){int a=side*offset+row*(sides+1)+i,b=a+sides+1;if(side==0)tris.AddRange(new[]{a,b,a+1,a+1,b,b+1});else tris.AddRange(new[]{a,a+1,b,a+1,b+1,b});}for(int end=0;end<=rows;end+=rows)for(int i=0;i<sides;i++){int a=end*(sides+1)+i,b=a+offset;tris.AddRange(new[]{a,a+1,b,a+1,b+1,b});}var mesh=new Mesh();mesh.SetVertices(vertices);mesh.SetUVs(0,uv);mesh.SetTriangles(tris,0);return mesh;});
  public static ServingArm Arm(SportsEventTruck truck,string folder,Material metal,Material trim){var arm=truck.gameObject.AddComponent<ServingArm>();arm.truck=truck;var gear=new GameObject("Compatible articulated serving equipment only").transform;gear.SetParent(truck.transform,false);arm.gear=gear;var block=Block(folder);Rigidbody link(string name){var g=Part(folder,gear,name,block,metal,Vector3.zero,new Vector3(.35f,3,.35f));var b=g.AddComponent<Rigidbody>();b.isKinematic=true;b.mass=40;b.interpolation=RigidbodyInterpolation.Interpolate;g.AddComponent<BoxCollider>();return b;}arm.shoulder=link("PhysX telescoping shoulder link");arm.elbow=link("PhysX articulated elbow link");var wrist=new GameObject("Native serving wrist and articulated tray");wrist.transform.SetParent(gear,false);arm.grip=wrist.AddComponent<Rigidbody>();arm.grip.mass=25;arm.grip.isKinematic=true;arm.grip.interpolation=RigidbodyInterpolation.Interpolate;var plate=Part(folder,wrist.transform,"Machined articulated support tray",Block(folder),trim,new Vector3(0,-.35f,0),new Vector3(2.8f,.14f,2.8f));plate.AddComponent<BoxCollider>();var sensor=wrist.AddComponent<SphereCollider>();sensor.radius=1.2f;sensor.isTrigger=true;var contact=wrist.AddComponent<ServingContact>();contact.arm=arm;for(int side=-1;side<=1;side+=2){var jaw=Part(folder,wrist.transform,"Modeled serving gripper finger",Block(folder),metal,new Vector3(side*1.2f,.15f,0),new Vector3(.15f,1,.5f));jaw.transform.localRotation=Quaternion.Euler(0,0,side*10);}
   arm.contacts=truck.GetComponentsInChildren<Collider>(true);arm.Move(truck.transform.TransformPoint(new Vector3(0,2.5f,7)),0,true);return arm;}
  public static ServingVessel Vessel(SportsEventSession session,MonoBehaviour events,string folder,Transform parent,string name,int id,Vector3 p,bool pot,Material porcelain,Material gold,Material tea,PhysicsMaterial contact){var root=new GameObject(name);root.layer=2;root.transform.SetParent(parent,false);root.transform.position=p;var rb=root.AddComponent<Rigidbody>();rb.mass=pot?18:8;rb.isKinematic=true;rb.linearDamping=.2f;rb.angularDamping=.25f;rb.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;rb.interpolation=RigidbodyInterpolation.Interpolate;rb.maxDepenetrationVelocity=2;root.AddComponent<ServingSupport>();var vessel=root.AddComponent<ServingVessel>();vessel.session=session;vessel.events=events;vessel.body=rb;vessel.id=id;vessel.spawn=p;vessel.capacity=pot?4.2f:1;vessel.initialVolume=pot?3.6f:0;vessel.pourable=pot;vessel.contents=ServingContents.Tea;vessel.maximumHealth=pot?1.5f:1;vessel.breakSpeed=pot?4.8f:3.8f;
   var shell=new GameObject("Finished glazed porcelain and gold decoration").transform;shell.SetParent(root.transform,false);vessel.shell=shell;Part(folder,shell,pot?"Hand-thrown teapot":"Actual hollow teacup",pot?Pot(folder):Cup(folder),porcelain,Vector3.zero,Vector3.one);var colliders=new List<Collider>();if(pot){var c=root.AddComponent<SphereCollider>();c.center=Vector3.up;c.radius=1;c.sharedMaterial=contact;colliders.Add(c);var spout=Part(folder,shell,"Curved open spout",Spout(folder),porcelain,Vector3.zero,Vector3.one);var spoutCollider=spout.AddComponent<MeshCollider>();spoutCollider.sharedMesh=Spout(folder);spoutCollider.convex=true;spoutCollider.sharedMaterial=contact;colliders.Add(spoutCollider);var lip=Part(folder,shell,"Gold bound pouring tip",Ring(folder),gold,new Vector3(0,1.1f,2.2f),Vector3.one*.17f);lip.transform.localRotation=Quaternion.Euler(90,0,0);var tip=new GameObject("Actual physical spout origin").transform;tip.SetParent(root.transform,false);tip.localPosition=new Vector3(0,1.1f,2.24f);vessel.spout=tip;Part(folder,shell,"Domed porcelain lid",Disk(folder),porcelain,Vector3.up*1.75f,new Vector3(.75f,1,.75f));Part(folder,shell,"Gold lid finial",Mesh(folder,"Glazed teapot finial",ImpossibleBalanceArt.Ovoid),gold,Vector3.up*1.98f,Vector3.one*.35f);}
   else {var bottom=root.AddComponent<BoxCollider>();bottom.center=Vector3.up*.1f;bottom.size=new Vector3(1.35f,.2f,1.35f);bottom.sharedMaterial=contact;colliders.Add(bottom);for(int i=0;i<12;i++){float a=i*Mathf.PI*2/12;var wall=new GameObject("Exact hollow porcelain wall "+i);wall.layer=2;wall.transform.SetParent(root.transform,false);wall.transform.localPosition=new Vector3(Mathf.Sin(a)*.83f,.8f,Mathf.Cos(a)*.83f);wall.transform.localRotation=Quaternion.Euler(0,a*Mathf.Rad2Deg,0);var c=wall.AddComponent<BoxCollider>();c.size=new Vector3(.47f,1.4f,.13f);c.sharedMaterial=contact;colliders.Add(c);}Part(folder,shell,"Rolled gold tea rim",Ring(folder),gold,Vector3.up*1.4f,Vector3.one*.96f);}
   var handle=Part(folder,shell,"Curved porcelain loop handle",Ring(folder),porcelain,new Vector3(-1.15f,.9f,0),new Vector3(.7f,.7f,.7f));handle.transform.localRotation=Quaternion.Euler(90,0,0);var surface=Part(folder,root.transform,"Actual finite liquid fill surface",Disk(folder),tea,Vector3.up*.15f,new Vector3(.73f,.2f,.73f));vessel.liquid=surface.transform;surface.SetActive(pot);var stream=new GameObject("Actual ballistic optimized liquid stream").AddComponent<LineRenderer>();stream.transform.SetParent(root.transform,false);stream.useWorldSpace=true;stream.startWidth=.085f;stream.endWidth=.035f;stream.sharedMaterial=tea;stream.numCapVertices=3;stream.enabled=false;vessel.stream=stream;vessel.physical=colliders.ToArray();vessel.fragments=new Rigidbody[6];for(int i=0;i<6;i++){var frag=Part(folder,root.transform,"Pooled broken porcelain shard "+i,Block(folder),porcelain,new Vector3(Mathf.Cos(i)*.55f,.35f+i*.18f,Mathf.Sin(i)*.55f),new Vector3(.65f,.12f,.45f));frag.layer=2;var c=frag.AddComponent<BoxCollider>();c.sharedMaterial=contact;var b=frag.AddComponent<Rigidbody>();b.mass=1;b.maxDepenetrationVelocity=2;b.isKinematic=true;vessel.fragments[i]=b;frag.SetActive(false);}foreach(var t in root.GetComponentsInChildren<Transform>(true))t.gameObject.layer=2;return vessel;}
  public static GameObject Prop(string folder,string path,Transform parent,Vector3 p,Vector3 size){var asset=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(asset==null)throw new InvalidOperationException("Installed serving venue art required: "+path);var root=new GameObject(asset.name+" owned venue instance").transform;root.SetParent(parent,false);root.position=p;var instance=(GameObject)PrefabUtility.InstantiatePrefab(asset,root);foreach(var script in instance.GetComponentsInChildren<MonoBehaviour>(true))UnityEngine.Object.DestroyImmediate(script);foreach(var collider in instance.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(collider);foreach(var body in instance.GetComponentsInChildren<Rigidbody>(true))UnityEngine.Object.DestroyImmediate(body);var renderers=instance.GetComponentsInChildren<Renderer>();if(renderers.Length==0)throw new InvalidOperationException("Serving venue art has no mesh.");Bounds bounds=renderers[0].bounds;foreach(var renderer in renderers)bounds.Encapsulate(renderer.bounds);float scale=Mathf.Min(size.x/Mathf.Max(.001f,bounds.size.x),size.y/Mathf.Max(.001f,bounds.size.y),size.z/Mathf.Max(.001f,bounds.size.z));instance.transform.localScale*=scale;bounds=renderers[0].bounds;foreach(var renderer in renderers)bounds.Encapsulate(renderer.bounds);instance.transform.position+=p-bounds.center;foreach(var renderer in renderers){var materials=renderer.sharedMaterials;for(int i=0;i<materials.Length;i++){var source=materials[i];if(source==null||source.shader.name.Contains("Universal Render Pipeline"))continue;string id=AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(source));var owned=ImpossibleBalanceArt.Material(folder,"Owned serving URP "+source.name+id,source.HasProperty("_Color")?source.color:Color.white);owned.mainTexture=source.mainTexture;materials[i]=owned;}renderer.sharedMaterials=materials;}return root.gameObject;}
 }
}
